// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {ERCDDAToken} from "../src/ERCDDAToken.sol";

contract InvMutTest is Test {
    ERCDDAToken c;

    function setUp() public { c = new ERCDDAToken(0, "", ""); }

    function testFuzz_property(uint256 amount) public {
        vm.assume(amount > 0);
        vm.prank(c.owner());
        c.mintToken(c.owner(), amount);
        uint256 preTotal = c.totalSupply();
        vm.prank(c.owner());
        c.burn(amount);
        uint256 postTotal = c.totalSupply();
        assertTrue(postTotal < preTotal);
    }
}
